/**
 * Detection of generated code from the header comment its generator wrote.
 *
 * Only comments count, and only the comments a file starts with: a code generator that holds its banner in
 * a string, or a hand-written file whose comment happens to say "do not edit", is not generated code.
 * Detection is language-agnostic: it knows the comment syntax of the common languages, not their grammars.
 */

/** Number of leading lines searched for a generated-code marker. */
export const GENERATED_MARKER_LINES = 10;

/**
 * Line comments: `//`, `#` (but not a `#!` shebang, `#include`-like directives or `#[attributes]`), and `--`
 * (SQL, Lua, Haskell) or `%` (Erlang, TeX) followed by a space.
 */
const LINE_COMMENT = /^(?:\/\/|#(?![\w!([{])|--(?=\s|$)|%(?=[\s%]|$))/;

/** Block comments, as opening and closing tokens. */
const BLOCK_COMMENTS: readonly (readonly [open: string, close: string])[] = [
  ["/*", "*/"],
  ["<!--", "-->"],
];

/** Lines that may precede a file's header comment: a shebang, `<?php`, `<?xml …?>`, `"use strict";`. */
const PROLOGUE = /^(?:#!|<\?php\b|<\?xml\b|(["'])use [a-z][a-z -]*\1;?$)/i;

/** Decoration before the words of a comment: `*` of block comments, repeated comment tokens, `!!!`. */
const DECORATION = /^[\s*!#/%=~+|-]*/;

/** A label such as `NOTE:` or `WARNING:`. */
const LABEL = /^(?:note|notice|warning|attention|important|caution)\b\s*[:!.-]*\s*/i;

/** A leading instruction followed by punctuation (`DO NOT EDIT. This file was generated by …`). */
const LEADING_INSTRUCTION =
  /^(?:do\s+not|don['\u2019]?t)\s+(?:edit|modify|change)\b(?:\s+(?:this\s+(?:file|code)|manually|by\s+hand|directly))?\s*[.!:;,\u2013\u2014-]+/i;

const AUTOMATIC = String.raw`(?:auto(?:matically)?[-\s]?|machine[-\s])?`;

/**
 * A statement that the file is generated, at the start of a comment: `Code generated by …` (Go's convention),
 * `Generated by|from|with|using …`, `AUTO-GENERATED FILE.`, `GENERATED CODE - …`, `This file was
 * (automatically) generated …`, `This is code generated by …`. A bare `generated` must be followed by
 * punctuation or `by`/`from`/`with`/`using`, so that `Generated files live in gen/` is not a statement.
 */
const STATEMENT = new RegExp(
  String.raw`^(?:this\s+(?:(?:file|code|class|module|script|header|source(?:\s+file)?)\s+)?(?:is|was|has\s+been)\s+(?:an?\s+)?(?:code\s+)?${AUTOMATIC}generated\b` +
    String.raw`|code\s+generated\b` +
    String.raw`|${AUTOMATIC}generated(?:\s+(?:code|file|source))?(?=$|\s*[.,;:!()\u2013\u2014-]|\s+(?:by|from|with|using)\b))`,
  "i",
);

/** An instruction not to edit: `DO NOT EDIT`, `do not modify`, `should not be edited`, `do not make changes`. */
const INSTRUCTION =
  /\b(?:do\s+not|don['\u2019]?t|must\s+not|should\s+not)\s+(?:be\s+)?(?:edit|modif|chang|make\s+(?:any\s+)?(?:direct\s+|manual\s+)?changes)/i;

/** Meta's convention (also Rust's prost, Cargo, Relay): the token `@generated`, not quoted. */
const AT_GENERATED = /(?:^|[\s(*/#!])@generated(?=$|[\s.,;:!)*])/;

/** The .NET convention: an `<auto-generated>` (or `<autogenerated>`) tag. */
const AUTO_GENERATED_TAG = /<auto-?generated\b/i;

/** One line of the header comment: its 1-based line number and the text of its comment. */
interface CommentLine {
  readonly line: number;
  readonly text: string;
}

/**
 * The comments a text starts with, within its first {@link GENERATED_MARKER_LINES} lines, grouped in blocks
 * of consecutive comment lines. Blank lines separate blocks; the first line of code ends the header (blank
 * lines and a prologue such as a shebang or `<?php` may precede it).
 */
function headerComments(text: string): CommentLine[][] {
  const blocks: CommentLine[][] = [];
  let block: CommentLine[] = [];
  const endBlock = (): void => {
    if (block.length > 0) blocks.push(block);
    block = [];
  };
  let closing: string | undefined;
  const lines = text.split("\n", GENERATED_MARKER_LINES);
  for (const [index, line] of lines.entries()) {
    const parts: string[] = [];
    let rest = line;
    if (closing !== undefined) {
      const end = rest.indexOf(closing);
      parts.push(end === -1 ? rest : rest.slice(0, end));
      rest = end === -1 ? "" : rest.slice(end + closing.length);
      if (end !== -1) closing = undefined;
    }
    const trimmed = rest.trim();
    let code = false;
    if (trimmed !== "") {
      const lineComment = LINE_COMMENT.exec(trimmed);
      const blockComment = BLOCK_COMMENTS.find(([open]) => trimmed.startsWith(open));
      if (lineComment !== null) {
        parts.push(trimmed.slice(lineComment[0].length));
      } else if (blockComment !== undefined) {
        const [open, close] = blockComment;
        const body = trimmed.slice(open.length);
        const end = body.indexOf(close);
        parts.push(end === -1 ? body : body.slice(0, end));
        if (end === -1) closing = close;
        else code = body.slice(end + close.length).trim() !== "";
      } else if (parts.length > 0 || !PROLOGUE.test(trimmed)) {
        code = true;
      }
    }
    if (parts.length > 0) block.push({ line: index + 1, text: parts.join(" ") });
    else endBlock();
    if (code) break;
  }
  endBlock();
  return blocks;
}

/** Whether a comment's text, once decoration, a label and a leading instruction are removed, says "generated". */
function isStatement(text: string): boolean {
  let words = text.replace(DECORATION, "").replace(LABEL, "");
  words = words.replace(LEADING_INSTRUCTION, "").replace(DECORATION, "");
  return STATEMENT.test(words);
}

/**
 * The 1-based line of the comment that marks a normalized text as generated code, or undefined. Only the
 * comments the text starts with count (see `headerComments`), within its first 10 lines; a comment line
 * marks the file when it:
 *
 * - holds the token `@generated` (Meta's convention: `// @generated`, ` * @generated SignedSource<<…>>`,
 *   `This file is @generated by prost-build.`);
 * - holds an `<auto-generated>` or `<autogenerated>` tag (the .NET convention);
 * - starts with a statement that the file is generated (`Code generated by …`, `Generated by …`,
 *   `AUTO-GENERATED FILE.`, `This file was automatically generated …`) and its block of comment lines tells
 *   not to edit it (`DO NOT EDIT`, `do not modify`, `should not be edited`). This covers Go's
 *   `// Code generated … DO NOT EDIT.`, protobuf's `Generated by the protocol buffer compiler.  DO NOT EDIT!`
 *   and Dart's `// GENERATED CODE - DO NOT MODIFY BY HAND`.
 *
 * A bare "do not edit" or "auto-generated", text in string literals and comments after the first line of
 * code do not count. Files whose generator writes no such header can be marked with the `generated` role
 * in the configuration.
 */
export function generatedMarkerLine(text: string): number | undefined {
  for (const block of headerComments(text)) {
    const instructed = block.some((comment) => INSTRUCTION.test(comment.text));
    for (const comment of block) {
      if (
        AT_GENERATED.test(comment.text) ||
        AUTO_GENERATED_TAG.test(comment.text) ||
        (instructed && isStatement(comment.text))
      ) {
        return comment.line;
      }
    }
  }
  return undefined;
}

/** Whether a normalized text declares itself generated code (see {@link generatedMarkerLine}). */
export function hasGeneratedMarker(text: string): boolean {
  return generatedMarkerLine(text) !== undefined;
}
